from decimal import Decimal, getcontext

def tri(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return [1]
    getcontext().prec = 100  # Set precision to avoid overflow
    sequence = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            next_term = Decimal(1) + Decimal(i) / Decimal(2)
        else:
            next_term = sum(sequence[i - 1:i + 2])
        sequence.append(int(next_term))
    return sequence
